#[derive(Clone, Copy, PartialEq, Eq, Hash)]
struct Key { rule: u32, pos: usize }
enum Memo { Ok { node: NodeId, next: usize }, Fail }

impl Parser<'_> {
    fn rule(&mut self, key: Key) -> Memo {
        if let Some(hit) = self.memo.get(&key) { return hit.clone(); } // borrow ends here
        let m = self.rule_impl(key);        // recursion needs &mut self again
        self.memo.insert(key, m.clone());   // failures become Memo::Fail entries
        m
    }
}

