#[derive(Clone, Copy)]
enum Memo { Unknown, Ok { node: NodeId, next: usize }, Fail }

struct Parser { memo: Vec<Memo>, cols: usize, arena: Vec<Node> }

impl Parser {
    fn rule(&mut self, rule: usize, pos: usize) -> Memo {
        let idx = rule * self.cols + pos;         // cols = len + 1
        if !matches!(self.memo[idx], Memo::Unknown) { return self.memo[idx]; }
        let m = self.rule_impl(rule, pos);
        self.memo[idx] = m;                       // failures cached as Fail
        m
    }
}
